        'mirrorExp.engineTranslation.upgrade': 'Upgrade path',
        'mirrorExp.engineTranslation.upgrade.value': 'React leaf plus optional isolated canvas after proof',
        'mirrorExp.engineTranslation.gate': 'Blocked by default',
        'mirrorExp.engineTranslation.gate.value': 'Camera, DOB authority, hidden memory, mobile always-on canvas',
        'mirrorExp.engineTranslation.states.aria': 'Translated Infinity Mirror engine states',
        'mirrorExp.engineTranslation.progress.label': 'Progress',
        'mirrorExp.engineTranslation.progress.title': 'Scroll becomes named stage.',
        'mirrorExp.engineTranslation.progress.desc': 'Tunnel, neural web, figure, network, and return become semantic chapters instead of hidden canvas weights.',
        'mirrorExp.engineTranslation.pointer.label': 'Pointer energy',
        'mirrorExp.engineTranslation.pointer.title': 'Interaction can deepen, not decide.',
        'mirrorExp.engineTranslation.pointer.desc': 'Cursor energy may enrich a desktop portal later, but no claim or route can depend on it.',
        'mirrorExp.engineTranslation.lens.label': 'Lens',
        'mirrorExp.engineTranslation.lens.title': 'Personalization stays reversible.',
        'mirrorExp.engineTranslation.lens.desc': 'Architect, Cartographer, Translator, and Ritualist remain presentation modes the human can change.',
        'mirrorExp.engineTranslation.artifact.label': 'Artifact',
