        'detail.fo.hero.kicker': 'Research / Web3 simulation',
        'detail.fo.hero.title': 'Financial organisms choose clarity before motion.',
        'detail.fo.hero.desc': 'The Financial Survival Organism exists to protect attention, capital, and decision quality. Its public posture is research and simulation first: no hidden wallet authority, no broadcast path, and no financial motion without explicit human approval.',
