        'detail.bc.hero.kicker': 'Experimental / Brain Cell Architecture',
        'detail.bc.hero.title': 'The brain that builds brains.',
        'detail.bc.hero.desc': 'Brain Cell Architecture is the reusable process for creating new AI organism capabilities. A cell is not trusted because it was generated. It is researched, bounded, sandboxed, tested, reviewed, and then integrated.',
        'detail.bc.hero.primary': 'Study the stack',
        'detail.bc.hero.secondary': 'Build a cell',
        'detail.bc.brief.title': 'Self-evolution needs an immune system.',
