        'detail.bc.capability.desc': 'Before lifecycle visuals turn self-evolution into a story, the page names the growth boundary: signal, research packet, sandbox trial, approval, integration, and rollback. A candidate cell can be proposed; it cannot join the organism until proof says yes.',
