        'detail.bc.capability.research.title': 'Research the cell before code earns attention.',
        'detail.bc.capability.research.desc': 'A generated class is not trusted because it sounds plausible. The research packet names assumptions, interfaces, tests, risk, and rollback first.',
        'detail.bc.capability.research.memory': 'Only reviewed failures, source context, public docs, and proof artifacts inform candidate design.',
