        'detail.bc.capability.integration.approval': 'Human review, source-control history, proof packet, and rollback path approve or refuse integration.',
        'detail.bc.capability.integration.output': 'An integrated or refused cell with visible proof and a rollback route.',
        'detail.bc.capability.integration.blocked': 'No irreversible self-evolution, hidden memory write, authority expansion, or unreviewed autonomy.',
