        // FAQ
        'faq.tag': 'Plain Answers',
        'faq.title': 'Questions serious visitors ask first.',
        'faq.desc': 'Short answers for builders, investors, users, collaborators, and AI crawlers trying to understand what Unwind Code means by organisms, not apps.',
        'faq.1.q': 'What is an AI organism?',
        'faq.1.a': 'An AI organism is a memory-bearing, tool-using system with a cortex, specialized cells, safety boundaries, and a proof loop. It can perceive, decide, act, remember, and improve under human authority.',
        'faq.2.q': 'How is an organism different from an app?',
        'faq.2.a': 'An app usually waits for input and resets context. An organism carries state forward, routes work through cells, pauses at risk gates, and records evidence so humans can inspect what happened.',
        'faq.3.q': 'Can Financial Organisms move money?',
        'faq.3.a': 'Financial Organisms are research and simulation lanes. On-chain intelligence and Web3 architecture stay bounded by unsigned review packets, proof, and human approval before any money motion.',
        'faq.4.q': 'Where can I inspect proof?',
        'faq.4.a': 'Start with the <a href="/proof/">Proof Ledger</a> and the <a href="/transmissions/">Transmissions</a>. They expose architecture notes, safety gates, status labels, and build artifacts.',
        'faq.5.q': 'How do I build with Unwind Code?',
        'faq.5.a': 'Use the <a href="/build-with-us/">Build With Us</a> path. Bring a goal, an authority boundary, and a proof requirement; the lab maps it into an organism architecture.',

