        'mirrorExp.audit.desc': 'La Fase 1 queda visible: la referencia se descompone en diez lentes de diseño y se reinterpreta como comportamiento de organismo atado a prueba, no como estilo de superficie copiado.',
        'mirrorExp.audit.packetCta': 'Abrir auditoría completa de experiencia',
