        'mirrorExp.audit.information.label': '01 / Arquitectura de información',
        'mirrorExp.audit.information.title': 'La escala necesita una columna legible.',
        'mirrorExp.audit.information.purpose': 'Mover de señal humana a método, hallazgos, prueba e implicaciones sin perder orientación.',
        'mirrorExp.audit.information.works': 'El visitante siempre sabe si está en historia, evidencia o espacio de decisión.',
        'mirrorExp.audit.information.reinterpret': 'El espejo usa capítulos, rieles, rutas de prueba y puertas de autoridad visibles como columna.',
        'mirrorExp.audit.story.label': '02 / Flujo narrativo',
        'mirrorExp.audit.story.title': 'La emoción entra antes que la abstracción.',
        'mirrorExp.audit.story.purpose': 'Hacer que una investigación grande se sienta humana antes de que aparezcan los sistemas.',
        'mirrorExp.audit.story.works': 'Esperanza y alarma permanecen juntas, así la experiencia se siente honesta y no promocional.',
        'mirrorExp.audit.story.reinterpret': 'La ruta comienza con reflexión y luego revela células cerebrales, organismos, prueba y elecciones.',
        'mirrorExp.audit.scroll.label': '03 / Coreografía de scroll',
        'mirrorExp.audit.scroll.title': 'El scroll dirige atención, no espectáculo.',
        'mirrorExp.audit.scroll.purpose': 'Presentar una idea a la vez mientras un campo visual persistente conserva continuidad.',
        'mirrorExp.audit.scroll.works': 'La página desacelera al lector en los momentos exactos donde cambia el significado.',
        'mirrorExp.audit.scroll.reinterpret': 'Infinity se fractura en reflexión, ruta celular, órbita de organismo y regreso de prueba.',
        'mirrorExp.audit.motion.label': '04 / Sistema de movimiento',
        'mirrorExp.audit.motion.title': 'El movimiento debe nombrar estado.',
        'mirrorExp.audit.motion.purpose': 'Usar movimiento para mostrar progresión, comparación y foco, no para decorar el viewport.',
        'mirrorExp.audit.motion.works': 'Loops pequeños hacen que el sistema se sienta vivo mientras preservan el orden de lectura.',
        'mirrorExp.audit.motion.reinterpret': 'Cada carril de movimiento recibe disparo, duración, easing, fallback y condición de parada.',
        'mirrorExp.audit.hierarchy.label': '05 / Jerarquía visual',
        'mirrorExp.audit.hierarchy.title': 'El asombro necesita inspección cerca.',
        'mirrorExp.audit.hierarchy.purpose': 'Balancear momentos inmersivos con etiquetas, evidencia y controles de ruta compactos.',
        'mirrorExp.audit.hierarchy.works': 'Los visuales grandes abren curiosidad; la prueba cercana mantiene al lector en tierra.',
        'mirrorExp.audit.hierarchy.reinterpret': 'El portal siempre se acompaña de tarjetas de prueba, ledgers y anchors de siguiente ruta.',
        'mirrorExp.audit.typography.label': '06 / Sistema tipográfico',
        'mirrorExp.audit.typography.title': 'La voz separa asombro de prueba.',
        'mirrorExp.audit.typography.purpose': 'Usar jerarquía de tipo para separar tesis, evidencia, etiquetas y caveats.',
        'mirrorExp.audit.typography.works': 'Los lectores pueden escanear el claim emocional y aun inspeccionar la maquinaria.',
        'mirrorExp.audit.typography.reinterpret': 'El lenguaje humano carga la tesis; las etiquetas mono cargan estado, puertas y prueba.',
        'mirrorExp.audit.transition.label': '07 / Lógica de transición',
        'mirrorExp.audit.transition.title': 'Cada capítulo cambia el trabajo del visitante.',
        'mirrorExp.audit.transition.purpose': 'Pasar de sensación a comparación, luego arquitectura, luego prueba y luego acción.',
        'mirrorExp.audit.transition.works': 'Nunca se le pide al lector juzgar toda la tesis de una vez.',
        'mirrorExp.audit.transition.reinterpret': 'Cada transición hace una pregunta más estrecha: qué cambió, qué actúa, qué lo prueba.',
        'mirrorExp.audit.attention.label': '08 / Gestión de atención',
        'mirrorExp.audit.attention.title': 'La elección aparece después de la orientación.',
        'mirrorExp.audit.attention.purpose': 'Retrasar interacción pesada hasta que el visitante entiende el marco.',
        'mirrorExp.audit.attention.works': 'La página gana atención antes de pedir exploración o conversión.',
        'mirrorExp.audit.attention.reinterpret': 'Rutas por rol, botones de lente y puertas de prueba aparecen solo después de que el espejo se explica.',
        'mirrorExp.audit.emotion.label': '09 / Progresión emocional',
        'mirrorExp.audit.emotion.title': 'El asombro debe aterrizar como confianza.',
        'mirrorExp.audit.emotion.purpose': 'Mover de curiosidad a reconocimiento, tensión, agencia y siguiente acción aterrizada.',
        'mirrorExp.audit.emotion.works': 'El final se siente ganado porque la experiencia admitió límites en el camino.',
        'mirrorExp.audit.emotion.reinterpret': 'El espejo puede sentirse vivo, pero cada claim vivo regresa con límite y prueba.',
        'mirrorExp.audit.performance.label': '10 / Técnica de rendimiento',
        'mirrorExp.audit.performance.title': 'La capa cinematográfica se mantiene barata.',
