        'arch.runway.kicker': 'Pista de arquitectura',
        'arch.runway.title': 'Una petición solo gana acción después de sobrevivir el loop.',
        'arch.runway.desc': 'La promesa de la página se vuelve creíble cuando el stack se puede inspeccionar: entrada por gateway, contexto acotado, células especialistas, decisiones inmunes y prueba aparecen antes de que la autonomía reciba autoridad.',
        'arch.runway.signal.title': 'Señal de gateway',
        'arch.runway.signal.desc': 'El organismo recibe meta humana, canal, rol y forma de riesgo.',
        'arch.runway.context.title': 'Cerca de contexto',
