        'archPage.layer.cortex.desc': 'El loop de razonamiento que convierte metas, estado actual, memoria y evidencia en decisiones.',
        'archPage.layer.memory.label': 'Memoria',
        'archPage.layer.memory.title': 'Memoria',
        'archPage.layer.memory.desc': 'Almacenes de trabajo, procedimentales, semánticos y episódicos que evitan que las lecciones se evaporen entre ejecuciones.',
        'archPage.layer.gateway.label': 'Gateway',
        'archPage.layer.gateway.title': 'Gateway',
        'archPage.layer.gateway.desc': 'El sistema nervioso de entrada/salida para web, chat, Telegram, Discord, móvil, APIs y canales futuros.',
        'archPage.layer.immune.label': 'Sistema Inmune',
        'archPage.layer.immune.title': 'Sistema Inmune',
        'archPage.layer.immune.desc': 'Ejecución en sandbox, escaneo de riesgo, checkpoints de aprobación y rutas de rechazo antes de acciones inseguras.',
        'archPage.layer.cells.label': 'Células',
        'archPage.layer.cells.title': 'Células',
        'archPage.layer.cells.desc': 'Agentes especialistas para flujos creativos, reflexión personal, simulación Web3, seguridad y capacidades dinámicas.',
        'archPage.layer.proof.label': 'Proof Loop',
        'archPage.layer.proof.title': 'Proof Loop',
        'archPage.layer.proof.desc': 'Tests, transmisiones, paquetes de release, docs de arquitectura y evidencia pública que vuelven el progreso inspeccionable.',
        'archPage.flow.title': 'Por qué esto es distinto de una app.',
        'archPage.flow.desc': 'Una app espera input y reinicia contexto. Un organismo conserva estado, enruta trabajo por células especializadas, se detiene ante compuertas de riesgo y registra lo ocurrido para revisión humana.',
        'archPage.step.perceive.title': 'Percibir',
        'archPage.step.perceive.desc': 'Las entradas llegan por canales, no solo formularios.',
        'archPage.step.decide.title': 'Decidir',
        'archPage.step.decide.desc': 'El Córtex usa memoria y evidencia antes de actuar.',
        'archPage.step.act.title': 'Actuar',
        'archPage.step.act.desc': 'Las células usan herramientas solo dentro de autoridad limitada.',
        'archPage.step.pause.title': 'Pausar',
        'archPage.step.pause.desc': 'Las operaciones de alto riesgo preguntan primero al creador.',
        'archPage.step.remember.title': 'Recordar',
        'archPage.step.remember.desc': 'Debriefs y artefactos de prueba hacen más aguda la siguiente ejecución.',

        // Philosophy
        'phil.tag': 'Lo que Creemos',
        'phil.title': 'Los Innegociables.',
        'phil.gateway.core.label': 'Directiva principal',
        'phil.gateway.core.title': 'Doctrina → límite',
        'phil.gateway.kicker': 'Doctrina operativa',
        'phil.gateway.title': 'El organismo solo sirve si protege al humano.',
        'phil.gateway.desc': 'La directiva principal no es una vibra. Se convierte en ley de producto: el dinero protege agencia, la claridad viene antes del movimiento, la prueba pública limita afirmaciones y la autoridad de alto riesgo sigue aprobada por humanos.',
        'phil.gateway.armor.label': 'Armadura',
        'phil.gateway.armor.desc': 'El dinero se enmarca como protección para atención, estabilidad y elección.',
        'phil.gateway.clarity.label': 'Claridad',
        'phil.gateway.clarity.desc': 'El sistema nombra estado, riesgo y siguiente acción antes de moverse.',
        'phil.gateway.authority.label': 'Autoridad',
        'phil.gateway.authority.desc': 'Archivos, dinero, publicaciones públicas y broadcast Web3 pausan para aprobación.',
        'phil.gateway.proof.label': 'Prueba',
        'phil.gateway.proof.desc': 'Las afirmaciones quedan atadas a arquitectura, tests, transmisiones o desconocidos explícitos.',
        'phil.gateway.cta': 'Lee la doctrina operativa',
        'phil.1.title': 'Cuestiona lo Establecido',
        'phil.1.desc': 'Si todos lo hacen así, esa es razón para mirar más a fondo. Deconstruimos cada decisión hasta sus principios fundamentales y reconstruimos solo lo que se gana su lugar. La solución elegante siempre es la correcta.',
        'phil.2.title': 'Construye para el Mundo que Viene',
        'phil.2.desc': 'No diseñamos para las limitaciones de hoy. Diseñamos para un mundo donde las máquinas negocian con máquinas y los datos se mueven cien veces más rápido. Todo lo que entregamos es compatible con el futuro por defecto.',
        'phil.3.title': 'Todo es Reemplazable',
        'phil.3.desc': 'Cada módulo, cada agente, cada componente — intercambiable sin romper el sistema. Sin monolitos. Sin dependencia. Si una pieza no se puede remover limpiamente, la arquitectura no está terminada.',
        'phil.4.title': 'Menos Ruido. Más Señal.',
        'phil.4.desc': 'Creemos que el código bello rinde mejor. Cero sobrecarga. Cero relleno. Si un diseño de sistema no es elegante, no está terminado — porque la complejidad es señal de que no has pensado lo suficiente.',
        'phil.5.title': 'Verdad Sobre Conveniencia',
        'phil.5.desc': 'Cada afirmación se verifica. Cada solución se somete a prueba contra la deuda técnica a largo plazo. Si no resiste el escrutinio, se descarta — porque la confianza es la base de todo lo que construimos.',

        // Philosophy Page
        'philPage.hero.kicker': 'Doctrina operativa',
        'philPage.hero.title': 'Dinero como armadura, no como dios. Baja el sufrimiento. Aumenta la claridad. Preserva la luz.',
        'philPage.hero.desc': 'Esta es la directiva principal detrás del trabajo de organismos. La autonomía solo sirve cuando protege la agencia humana, mejora la claridad y se niega a convertir el riesgo en identidad.',
        'philPage.hero.primary': 'Estudiar la arquitectura',
        'philPage.hero.secondary': 'Inspeccionar prueba',
