        // FAQ
        'faq.tag': 'Respuestas Claras',
        'faq.title': 'Preguntas que hacen primero los visitantes serios.',
        'faq.desc': 'Respuestas breves para builders, inversionistas, usuarios, colaboradores y crawlers de IA que intentan entender qué significa organismos, no apps.',
        'faq.1.q': '¿Qué es un organismo de IA?',
        'faq.1.a': 'Un organismo de IA es un sistema con memoria, herramientas, córtex, células especializadas, límites de seguridad y proof loop. Puede percibir, decidir, actuar, recordar y mejorar bajo autoridad humana.',
        'faq.2.q': '¿En qué se diferencia un organismo de una app?',
        'faq.2.a': 'Una app normalmente espera input y reinicia contexto. Un organismo conserva estado, enruta trabajo por células, pausa ante compuertas de riesgo y registra evidencia para revisión humana.',
        'faq.3.q': '¿Pueden los Organismos Financieros mover dinero?',
        'faq.3.a': 'Los Organismos Financieros son rutas de investigación y simulación. La inteligencia on-chain y la arquitectura Web3 se mantienen limitadas por paquetes sin firma, prueba y aprobación humana antes de cualquier movimiento de dinero.',
        'faq.4.q': '¿Dónde puedo inspeccionar la prueba?',
        'faq.4.a': 'Empieza con el <a href="/proof/">Proof Ledger</a> y las <a href="/transmissions/">Transmisiones</a>. Exponen notas de arquitectura, compuertas de seguridad, etiquetas de estado y artefactos de construcción.',
        'faq.5.q': '¿Cómo construyo con Unwind Code?',
        'faq.5.a': 'Usa la ruta <a href="/build-with-us/">Construye con Nosotros</a>. Trae un objetivo, un límite de autoridad y un requisito de prueba; el laboratorio lo convierte en arquitectura de organismo.',

